using System.Linq;
using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace Ulbra.One.SourceGenerators;

[Generator]
public sealed class PrefixedIdGenerator : IIncrementalGenerator
{
    private const string AttributeMetadataName = "Ulbra.One.Common.Application.Ids.PrefixedIdAttribute";

    private const string AttributeSource = """
        // <auto-generated/>
        #nullable enable
        namespace Ulbra.One.Common.Application.Ids
        {
            [global::System.AttributeUsage(global::System.AttributeTargets.Struct)]
            internal sealed class PrefixedIdAttribute : global::System.Attribute
            {
                public PrefixedIdAttribute(string prefix) => Prefix = prefix;
                public string Prefix { get; }
            }
        }
        """;

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        context.RegisterPostInitializationOutput(static ctx =>
            ctx.AddSource("PrefixedIdAttribute.g.cs", SourceText.From(AttributeSource, Encoding.UTF8)));

        var ids = context.SyntaxProvider.ForAttributeWithMetadataName(
            AttributeMetadataName,
            predicate: static (node, _) => node is RecordDeclarationSyntax,
            transform: static (ctx, _) =>
            {
                var symbol = (INamedTypeSymbol)ctx.TargetSymbol;
                var prefix = ctx.Attributes[0].ConstructorArguments.Length > 0
                    ? ctx.Attributes[0].ConstructorArguments[0].Value as string ?? ""
                    : "";
                var ns = symbol.ContainingNamespace.IsGlobalNamespace
                    ? null
                    : symbol.ContainingNamespace.ToDisplayString();
                return new IdModel(symbol.Name, ns, prefix);
            });

        context.RegisterSourceOutput(ids, static (ctx, model) =>
            ctx.AddSource($"{model.Name}.g.cs", SourceText.From(Emit(model), Encoding.UTF8)));

        // Collect all ids and emit a registry for bulk OpenAPI registration.
        var allIds = ids.Collect();
        context.RegisterSourceOutput(allIds, static (ctx, models) =>
            ctx.AddSource("PrefixedIdRegistry.g.cs", SourceText.From(EmitRegistry(models), Encoding.UTF8)));
    }

    private readonly record struct IdModel(string Name, string? Namespace, string Prefix);

    private static string EmitRegistry(System.Collections.Immutable.ImmutableArray<IdModel> models)
    {
        // Sort by type name for deterministic output.
        var sorted = models.OrderBy(m => m.Name).ToArray();

        var entries = new StringBuilder();
        foreach (var m in sorted)
        {
            var fullName = m.Namespace is null
                ? m.Name
                : $"{m.Namespace}.{m.Name}";
            entries.AppendLine($"            (typeof(global::{fullName}), \"{m.Prefix}3fa85f64571742199730000000000000\"),");
        }

        return $$"""
            // <auto-generated/>
            #nullable enable
            namespace Ulbra.One.Common.Application.Ids
            {
                public static class PrefixedIdRegistry
                {
                    public static readonly global::System.Collections.Generic.IReadOnlyList<(global::System.Type Type, string Example)> All =
                        new (global::System.Type, string)[]
                        {
            {{entries.ToString().TrimEnd()}}
                        };
                }
            }
            """;
    }

    private static string Emit(IdModel m)
    {
        var n = m.Name;
        var body = $$"""
                [global::System.Text.Json.Serialization.JsonConverter(typeof(global::Ulbra.One.Common.Application.Ids.PrefixedIdJsonConverter<{{n}}>))]
                public readonly partial record struct {{n}}
                    : global::Ulbra.One.Common.Application.Ids.IPrefixedId, global::System.IParsable<{{n}}>
                {
                    public static string Prefix => "{{m.Prefix}}";

                    public static {{n}} New() => new(global::System.Guid.NewGuid());

                    public override string ToString() => Prefix + Value.ToString("N");

                    public static {{n}} Parse(string s, global::System.IFormatProvider? provider) =>
                        TryParse(s, provider, out var r) ? r : throw new global::System.FormatException($"Invalid {{n}}: {s}");

                    public static bool TryParse(string? s, global::System.IFormatProvider? provider, out {{n}} result)
                    {
                        result = default;
                        if (string.IsNullOrEmpty(s)) return false;
                        var raw = s!.StartsWith(Prefix, global::System.StringComparison.Ordinal) ? s.Substring(Prefix.Length) : s;
                        if (!global::System.Guid.TryParse(raw, out var g)) return false;
                        result = new {{n}}(g);
                        return true;
                    }
                }
        """;
        var src = m.Namespace is null
            ? body
            : $"namespace {m.Namespace}\n{{\n{body}\n}}";
        return "// <auto-generated/>\n#nullable enable\n" + src + "\n";
    }
}
